// Version A: rAF loop + setState + layout property
useEffect(() => {
  let raf;
  const tick = () => {
    setX((x) => x + 6);
    raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);
  return () => cancelAnimationFrame(raf);
}, []);
// rendered as: <div className="drawer" style={{ left: x }} />

